const items = $input.all();
const gmail = $('When Gmail Receives Hourly Messages').first().json;

const managers = [];
const companies = [];

for (const item of items) {
  const data = item.json;

  // Manager
  if (data.property_member_id) {
    managers.push({
      member_id: data.property_member_id,
      name: data.property_name,
      email: data.property_email,
      active: data.property_active,
      department: data.property_department,
      responsibilities: data.property_responsibilities,
      notes: data.property_notes,
      experience_level: data.property_experience_level,
      specializations: data.property_specializations
    });
  }

  // Company
  if (data.property_company_id) {
    companies.push({
      company_id: data.property_company_id,
      company_name: data.property_company_name,
      domain: data.property_domain,
      assigned_member_id: data.property_assigned_member_id,
      assigned_member_name: data.property_assigned_member_name,
      primary_contact: data.property_primary_contact,
      contact_email: data.property_contact_email,
      relationship_status: data.property_relationship_status
    });
  }
}

return [{
  json: {
    email: {
      from: gmail.From,
      subject: gmail.Subject,
      body: gmail.snippet
    },
    managers,
    companies
  }
}];

